pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small to fit common items (10-20 range)
    // We prioritize bins that leave a residual which is a multiple of larger items (harmonic alignment)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Lookahead logic: If the next item is large, favor bins that preserve space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else {
            score += 10.0; // Penalize bins that cannot accommodate the next item
        }
    }

    // Harmonic class logic: Favor bins that align with modulo 25 (e.g., 25, 50, 75)
    // This helps pack items that are multiples of 25 (common in many distributions)
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 25.0;
    } else if remainder > 20 {
        score += 10.0;
    }

    // If this is the last chance for the current item, prioritize fitting it over new bin creation
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // Discourage opening too many bins early in the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    // Penalize bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger residuals to favor Best-Fit behavior.
    let mut score = post;

    // Penalty for opening a new bin: if this is a new bin, increase score significantly
    // based on the number of already open bins and progress.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * (1.0 - progress * 0.5)) * 20.0;

        // If we have other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Non-linear coupling: Reward placements that leave a residual which is a multiple of 
        // common item sizes (e.g., ~20-30), modified by the lookahead.
        // We punish residuals that are too small to fit typical items (e.g., < 15).
        if post > 0.0 && post < 15.0 {
            score += (15.0 - post) * 2.5;
        }

        // Lookahead integration: If the next item is large, prioritize leaving enough space.
        if next_item_size > 0 {
            let space_needed = next_item_size as f64;
            if post < space_needed {
                // Penalize leaving a gap that is too small for the next item
                score += (space_needed - post) * 1.5;
            }
        }
    }

    // Dynamic pressure: As the stream nears the end, become more aggressive in packing
    // to avoid leaving trailing items in new bins.
    score -= progress * (mean_residual * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: favor smaller post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space": if post_residual is small but > 0, it's often hard to fill.
    // If post_residual is in the range [1, 9], it's very likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If we have a next item, check if it fits in the remaining space (post_residual).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Good packing chain).
            score -= 15.0;
        } else {
            // Penalize bins that block the next item if the next item is large.
            if next_item_size > 50 {
                score += 10.0;
            }
        }
    }

    // 4. Global state awareness:
    // If fitting_bins_count is 1, we are at a critical juncture for this item.
    // Avoid opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Only pick this if we have many bins already or if fitting_bins_count is small/zero.
        score += 40.0; 
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // If we are placing into an existing bin, incentivize filling bins that are already "half-empty"
        // to keep the number of active bins low.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Dynamic time horizon:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 50.0; // Heavy penalty for new bins near end
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (splinters) that are unusable for common item sizes
    // Splinter penalty is higher when we are near the end of the stream
    let splinter_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Favor bins that align with the lookahead item size to prevent bin fragmentation
    let lookahead_penalty = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            0.0
        } else {
            (next_item_size as f64 - post) * 1.5
        }
    } else {
        0.0
    };

    // Calculate score: prioritize minimizing post_residual (Best Fit)
    // but subtract weight based on open_bins_count to encourage consolidation
    // and add penalties for creating splinters or failing to accommodate lookahead.
    let mut score = post * 1.0 
        + splinter_penalty 
        + lookahead_penalty 
        - (open_bins_count as f64 * 0.5 * (1.0 - progress));

    // If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the penalty for using existing bins is extremely high.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality in existing bins is poor
        // or if we have very few open bins (avoiding unnecessary bin creation).
        score = 25.0 + (progress * 10.0);
    }

    score
