pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), 
    // but we modify this based on the likelihood of future items fitting into the remaining space.

    // Penalty for creating a bin that is "too empty" (large post_residual)
    // We scale the importance of a tight fit based on the progress of the stream.
    // As we approach the end of the stream, we become more aggressive about filling bins (Best Fit).
    let mut score = post * (1.0 + progress);

    // Lookahead mechanism: If the next item is large, penalize bins that leave 
    // a residual smaller than the next_item_size, as this creates stranded capacity.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Heuristic for opening a new bin: 
    // Only open a new bin if the current bin is "nearly perfect" or if we are forced.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the existing bins are quite full 
        // (mean_residual is low) or if we are nearing the end of the stream 
        // and need to avoid fragmentation.
        score = 25.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // If it's an existing bin, penalize bins that have a large residual 
        // compared to the global average (to promote consolidation).
        if post > mean_residual {
            score += (post - mean_residual) * 0.8;
        }
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new one 
    // unless the fit is extremely poor (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

