    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: scales with how much space is left in existing bins
        // and current progress. If we are early in the stream, we are more conservative.
        score = 25.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Best Fit Decreasing logic: prioritize tight fits.
        // We penalize large post_residuals (dead space).
        score = post_residual as f64;

        // Lookahead heuristic: If the next item can fit in the current post_residual,
        // we reward this bin placement significantly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }

        // Penalty for creating "orphan" space that is too small for common items (e.g., < 15).
        if post_residual > 0 && post_residual < 15 {
            score += 12.0;
        }

        // If this is the last fitting bin, we are forced to use it; reward filling it
