        if fitting_bins_count == 1 {
            score -= 5.0;
        }

        // Dynamic thresholding: as the stream progresses, prioritize closing bins
        // (making post_residual close to 0) to reduce open_bins_count.
        score += (open_bins_count as f64 * progress);
    }

    score
}

