pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We penalize large residuals to encourage Best-Fit behavior (minimizing waste).
    let mut score = post;

    // Penalty for leaving "unusable" space (e.g., < 10) that is hard to fill later.
    // This creates a non-linear "valley" where we prefer post-residuals near 0 
    // or large enough to accommodate the average future item.
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead coupling: If a second item is known, favor bins that leave enough
    // room for it, or bins that perfectly match the current item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 10.0 * (1.0 - (post - next) / bin_capacity as f64);
        } else {
            score += 15.0; // Penalty for stranding the next item
        }
    }

    // Dynamic density management:
    // As the stream progresses, prioritize closing bins (lower mean_residual) 
    // to avoid fragmentation in the final stages.
    let density_penalty = (mean_residual / bin_capacity as f64) * 20.0 * progress;
    score += density_penalty;

    // Favor existing bins over opening new ones unless the fit is catastrophic.
    // If fitting_bins_count is low, we are running out of options for this item.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // We only return a low score here if the existing bins are very poor (high post_residual).
        score += 40.0;
        score -= (open_bins_count as f64 * 2.0);
    } else {
        // Existing bin: reward based on how well it fits the item relative to capacity.
        score -= (bin_capacity as f64 - post) * 0.1;
    }

    score
}
